# Langue lue UNE fois sur le disque puis gardée en mémoire : tr() est appelé
# dans des paintEvent (plan de feu redessiné en continu), et relire le fichier
# à chaque appel faisait des dizaines d'accès disque par seconde au repos.
# set_language() est le seul écrivain du fichier : il met le cache à jour.
_LANG_CACHE: str | None = None


def get_language() -> str:
    """Return current language code ('en', 'fr', 'es', 'de', 'pt' or 'ja')."""
    global _LANG_CACHE
    if _LANG_CACHE is None:
        lang = _DEFAULT_LANG
        try:
            lu = _LANG_FILE.read_text(encoding="utf-8").strip().lower()
            if lu in _LANGS:
                lang = lu
        except Exception:
            pass
        _LANG_CACHE = lang
    return _LANG_CACHE


def set_language(lang: str) -> None:
    """Persist language choice ('en', 'fr', 'es', 'de', 'pt' or 'ja') to disk."""
    global _LANG_CACHE
    if lang not in _LANGS:
        raise ValueError(
            f"Unsupported language: {lang!r}  (use {', '.join(map(repr, _LANGS))})")
    _LANG_FILE.write_text(lang, encoding="utf-8")
    _LANG_CACHE = lang


_NAME_KEYS: dict[str, str] | None = None


def tr_name(text: str) -> str:
    """Traduit un libellé qui sert AUSSI de valeur enregistrée.

    Noms d'effets intégrés, formes, catégories… sont stockés en français dans
    les shows et comparés tels quels par le code : on ne les remplace jamais,
    on ne traduit qu'au moment de les AFFICHER. Les clés `nm_*` du dictionnaire
    portent la valeur dans leur champ "fr" ; un texte inconnu (nom choisi par
    l'utilisateur) est rendu tel quel.
    """
    global _NAME_KEYS
    if _NAME_KEYS is None:
        _NAME_KEYS = {v["fr"]: k for k, v in TRANSLATIONS.items() if k.startswith("nm_")}
    key = _NAME_KEYS.get(text)
    return tr(key) if key else text


def tr(key: str, **kwargs) -> str:
    """
    Translate *key* to the current language, formatting optional kwargs.
    Falls back to English if the key is missing for the current language.
    """
    lang = get_language()
    entry = TRANSLATIONS.get(key, {})
    text = entry.get(lang) or entry.get("en") or key
    return text.format(**kwargs) if kwargs else text
